// Extract the 11-character video ID from any YouTube URL format.
const url = $('Paste YouTube Video URL').first().json.videoUrl || '';
const m = url.match(/(?:youtube\.com\/(?:watch\?.*v=|shorts\/|embed\/)|youtu\.be\/)([\w-]{11})/);
if (!m) throw new Error('Could not extract a video ID from: ' + url);
return [{ json: { videoId: m[1], videoUrl: url } }];

// Normalize the transcript into the shared content shape.
const t = $input.first().json;
let text = t.text || '';
if (!text && Array.isArray(t.content)) text = t.content.map(c => c.text || '').join(' ');
return [{ json: {
  source: 'transcript',
  videoId: $('Extract Video ID').first().json.videoId,
  text: text.slice(0, 12000)
}}];

// Fallback: build content from the video title and description.
const s = $input.first().json.snippet || {};
const text = ((s.title || '') + '. ' + (s.description || '')).slice(0, 12000);
return [{ json: {
  source: 'title and description (transcript unavailable)',
  videoId: $('Extract Video ID').first().json.videoId,
  text
}}];

// Validate the carousel JSON and build the human-readable package.
const raw = ($input.first().json.text || '').replace(/```json|```/g, '').trim();

let slides = [];
try { slides = JSON.parse(raw); } catch (e) {}

const valid = Array.isArray(slides) && slides.length >= 4 && slides.every(s => s.headline && s.body);
if (!valid) return [{ json: { valid: false, raw } }];

const videoId = $('Extract Video ID').first().json.videoId;
const carouselText = slides.map((s, i) =>
  `— Slide ${s.slide || i + 1} —\n${s.headline}\n${s.body}\nVisual idea: ${s.visual || 'clean minimal layout'}`
).join('\n\n');

return [{ json: { valid: true, videoId, slides, slideCount: slides.length, carouselText } }];

parameters.prompt:
=You are a LinkedIn growth expert. Rate the caption below for virality from 1 to 10 based on hook strength, clarity, and call-to-action.

Caption to rate:
{{ $json.caption || $json.text }}

Return ONLY a raw JSON object, no markdown fences:
{"score": <integer 1-10>, "feedback": "<one short sentence>", "caption": "<the final caption — if the score is below 8, rewrite it stronger using the feedback; otherwise return it unchanged>"}

parameters.jsCode:
// Parse the virality rating and carry the caption forward.
const raw = ($input.first().json.text || '').replace(/```json|```/g, '').trim();
let r = {};
try { r = JSON.parse(raw); } catch (e) {}

const score = Number(r.score) || 0;
return [{ json: {
  caption: r.caption || '',
  score: score,
  feedback: r.feedback || '',
  carouselText: $('Validate Carousel JSON').first().json.carouselText,
  slideCount: $('Validate Carousel JSON').first().json.slideCount,
  videoId: $('Extract Video ID').first().json.videoId
}}];
